// Normalise what the brief form sent and decide whether it is usable.
const body = $json.body ?? $json;

const fields = body.fields ?? {};
const name   = String(fields.name ?? '').trim();
const kind   = String(body.kind ?? '').trim();
const pal    = String(body.palette ?? '').trim();
const lang   = body.lang === 'en' ? 'en' : 'ar';
const usedBefore = Number(body.used_before ?? 0);
const freeCount  = Number(body.free_count ?? 2);

const problems = [];
if (name.length < 1)  problems.push('name');
if (kind.length < 1)  problems.push('kind');
if (pal.length < 1)   problems.push('palette');

return [{
  json: {
    valid: problems.length === 0,
    problems,
    name, kind, palette: pal, lang,
    what: String(fields.what ?? '').trim(),
    who: String(fields.who ?? '').trim(),
    why: String(fields.why ?? '').trim(),
    offer: String(fields.offer ?? '').trim(),
    action: String(fields.action ?? '').trim(),
    contact: String(fields.contact ?? '').trim(),
    used_before: usedBefore,
    free_count: freeCount,
    billable: usedBefore >= freeCount,
    created_at: new Date().toISOString(),
    status: 'new',
  },
}];

